CREATE TYPE public.app_role AS ENUM ('admin');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated;
CREATE POLICY own_role ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.vehicles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), make text, model text, variant text, manufacturing_year integer CHECK(manufacturing_year BETWEEN 1886 AND 2100), price numeric(14,2) CHECK(price>=0), is_price_negotiable boolean NOT NULL DEFAULT false, kilometres_driven integer CHECK(kilometres_driven>=0), fuel_type text CHECK(fuel_type IN ('Petrol','Diesel','CNG','Electric','Hybrid','Other')), transmission text CHECK(transmission IN ('Manual','Automatic')), body_type text, registration_state text, previous_owners integer CHECK(previous_owners>=0), exterior_color text, short_description text, description text, features text[] NOT NULL DEFAULT '{}', specifications jsonb NOT NULL DEFAULT '{}', insurance_valid_until date, registration_valid_until date, service_history_status text, inspection_status text, primary_image_url text, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','sold','archived')), availability text NOT NULL DEFAULT 'available' CHECK(availability IN ('available','sold')), is_featured boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz);
GRANT SELECT ON public.vehicles TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.vehicles TO authenticated; GRANT ALL ON public.vehicles TO service_role;
ALTER TABLE public.vehicles ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_inventory ON public.vehicles FOR SELECT TO anon,authenticated USING(status='published' AND availability='available');
CREATE POLICY admin_vehicles ON public.vehicles FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE INDEX vehicles_public_order ON public.vehicles(status,availability,is_featured,published_at DESC);
CREATE INDEX vehicles_updated ON public.vehicles(updated_at DESC);
CREATE TABLE public.vehicle_private_details (vehicle_id uuid PRIMARY KEY REFERENCES public.vehicles(id) ON DELETE CASCADE, registration_number text, approved_public_display boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.vehicle_private_details TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.vehicle_private_details TO authenticated; GRANT ALL ON public.vehicle_private_details TO service_role;
ALTER TABLE public.vehicle_private_details ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_approved_registration ON public.vehicle_private_details FOR SELECT TO anon,authenticated USING(approved_public_display AND EXISTS(SELECT 1 FROM public.vehicles v WHERE v.id=vehicle_id AND v.status='published' AND v.availability='available'));
CREATE POLICY admin_private_details ON public.vehicle_private_details FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.vehicle_images (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vehicle_id uuid NOT NULL REFERENCES public.vehicles(id) ON DELETE CASCADE, image_path text NOT NULL UNIQUE, display_order integer NOT NULL DEFAULT 0 CHECK(display_order>=0), is_primary boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.vehicle_images TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.vehicle_images TO authenticated; GRANT ALL ON public.vehicle_images TO service_role;
ALTER TABLE public.vehicle_images ENABLE ROW LEVEL SECURITY;
CREATE INDEX vehicle_images_order ON public.vehicle_images(vehicle_id,display_order);
CREATE UNIQUE INDEX one_primary_image ON public.vehicle_images(vehicle_id) WHERE is_primary;
CREATE POLICY public_vehicle_images ON public.vehicle_images FOR SELECT TO anon,authenticated USING(EXISTS(SELECT 1 FROM public.vehicles v WHERE v.id=vehicle_id AND v.status='published' AND v.availability='available'));
CREATE POLICY admin_vehicle_images ON public.vehicle_images FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.validate_vehicle() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
IF NEW.status='sold' THEN NEW.availability='sold'; END IF;
IF NEW.status='published' THEN
IF coalesce(trim(NEW.make),'')='' OR coalesce(trim(NEW.model),'')='' OR NEW.manufacturing_year IS NULL OR NEW.price IS NULL OR NEW.price<=0 THEN RAISE EXCEPTION 'Make, model, manufacturing year and a positive asking price are required to publish.'; END IF;
IF NEW.availability<>'available' THEN RAISE EXCEPTION 'Sold vehicles cannot be published as available.'; END IF;
IF NEW.manufacturing_year>extract(year FROM now())::integer+1 THEN RAISE EXCEPTION 'Manufacturing year is invalid.'; END IF;
IF NEW.published_at IS NULL THEN NEW.published_at=now(); END IF;
END IF; NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TRIGGER validate_vehicle_before_save BEFORE INSERT OR UPDATE ON public.vehicles FOR EACH ROW EXECUTE FUNCTION public.validate_vehicle();
CREATE POLICY admin_image_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='vehicle-images' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY public_listing_image_read ON storage.objects FOR SELECT TO anon,authenticated USING(bucket_id='vehicle-images' AND EXISTS(SELECT 1 FROM public.vehicle_images i JOIN public.vehicles v ON v.id=i.vehicle_id WHERE i.image_path=name AND v.status='published' AND v.availability='available'));
CREATE POLICY admin_image_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='vehicle-images' AND public.has_role(auth.uid(),'admin') AND lower(storage.extension(name)) IN ('jpg','jpeg','png','webp') AND EXISTS(SELECT 1 FROM public.vehicles v WHERE v.id::text=(storage.foldername(name))[1]));
CREATE POLICY admin_image_update ON storage.objects FOR UPDATE TO authenticated USING(bucket_id='vehicle-images' AND public.has_role(auth.uid(),'admin')) WITH CHECK(bucket_id='vehicle-images' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY admin_image_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='vehicle-images' AND public.has_role(auth.uid(),'admin'));